export async function consumeWithBackpressure(consumer: Consumer, dbPool: Pool) {
  await consumer.run({
    eachBatch: async ({ batch, pause, resolveOffset, heartbeat }) => {
      for (const message of batch.messages) {
        // If downstream DB pool is exhausted, pause fetching
        if (dbPool.waitingCount > 50) {
          console.warn('DB overloaded! Pausing consumption for 5 seconds...');
          const resume = pause();
          setTimeout(() => resume(), 5000);
          break; // Stop processing current batch
        }

        await processRecord(message);
        resolveOffset(message.offset);
        await heartbeat(); // Keep coordinator lease alive
      }
    }
  });
}
